s=a+'''// tokenProviderDefined reports whether any of the provider's auth parameters
// is set, recording any that are defined but blank.
func tokenProviderDefined(provider string, errs *strings.Builder) bool {
	var defined bool

	for _, param := range enabledProviderAuth[provider] {
		val, exists := GetEnvOrFile(param)
		if !exists {
			continue
		}

		if strings.Trim(val, " ") == "" {
			_, _ = fmt.Fprintf(errs, "%s parameter '%s' is not defined.\\n", provider, param)
		} else {
			defined = true
		}
	}

	return defined
}

// allAuthParamsDefined reports whether all of the provider's auth parameters
// are set, recording the missing ones when only some are.
func allAuthParamsDefined(provider string, errs *strings.Builder) bool {
	var foundCount, totalCount int

	for _, param := range enabledProviderAuth[provider] {
		totalCount++

		val, exists := GetEnvOrFile(param)
		if exists && strings.Trim(val, " ") != "" {
			foundCount++
		}
	}

	if foundCount > 0 && foundCount < totalCount {
		for _, param := range enabledProviderAuth[provider] {
			val, exists := GetEnvOrFile(param)
			if !exists || strings.Trim(val, " ") == "" {
				_, _ = fmt.Fprintf(errs, "%s parameter '%s' is not defined.\\n", provider, param)
			}
		}
	}

	return foundCount == totalCount
}

